INSERT INTO "ResearchItem" ("id", "source", "type", "title", "summary", "evidence", "sourceUrl", "score", "status", "createdAt") VALUES
('cmutsnlxi0000eub8ammlkafa', 'builtin_research_pool', 'pain_point', 'Учёт в Excel ломается, когда объектов становится больше трёх', 'Таблицы ведутся вручную: даты платежей, депозиты, коммунальные платежи, индексация. Один пропущенный столбец или версия файла ''финал_2'' - и данные расходятся между собственниками и управляющими.', '{"signal":"recurrent_theme","confidence":"high","source":"domain_research_pool","web":[]}', NULL, 80, 'used', '2026-10-04T12:25:30.055Z'),
('cmutsnlxp0001eub8kh45tn2f', 'builtin_research_pool', 'trend', 'Короткие видео-обзоры продукта обгоняют текстовые обзоры по доверию', 'Собственники хотят видеть интерфейс и реальный сценарий работы, а не абстрактные обещания. Формат ''экран + 40 секунд сценария'' вызывает больше вопросов в комментариях, чем статичный пост.', '{"signal":"format_trend","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 60, 'used', '2026-10-04T12:25:30.062Z'),
('cmutsnlxt0002eub8jhlidgg7', 'builtin_research_pool', 'competitor_topic', 'Тема ''как принимать платежи'' - вечнозелёная в нише', 'Порядок приёма, подтверждения, депозиты и залоги регулярно поднимаются в сообществах арендодателей. Повод дать полезный материал без продаж в лоб.', '{"signal":"evergreen_topic","confidence":"high","source":"domain_research_pool","web":[]}', NULL, 50, 'used', '2026-10-04T12:25:30.066Z'),
('cmutsnlxx0003eub85iwl3srq', 'builtin_research_pool', 'seo_opportunity', 'Сравнительный интент: таблицы против системы учёта', 'Запросы формата ''как вести учёт аренды'' и ''программа для учёта арендаторов'' подразумевают выбор инструмента. Подходит для кластера со статьёй-сравнением.', '{"signal":"keyword_cluster","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 65, 'used', '2026-10-04T12:25:30.070Z'),
('cmutsnly10004eub81n6d1675', 'builtin_research_pool', 'audience_question', 'Как напоминать арендатору об оплате, чтобы не портить отношения', 'Баланс между настойчивостью и вежливостью - частый вопрос. Тон имеет значение: автоматическое напоминание снимает личный конфликт.', '{"signal":"community_question","confidence":"high","source":"domain_research_pool","web":[]}', NULL, 70, 'used', '2026-10-04T12:25:30.073Z'),
('cmuttcznh0000euks99y8a4l6', 'builtin_research_pool', 'pain_point', 'Нет ответа на главный вопрос: сколько приносит портфель', 'Доходность по объектам считают редко и вручную. Без вычета расходов цифра в голове обычно оптимистичнее реальной, поэтому решения о продаже или ремонте принимаются вслепую.', '{"signal":"recurrent_theme","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 80, 'used', '2026-10-04T12:45:14.238Z'),
('cmuttczno0001euksyyxc4wz1', 'builtin_research_pool', 'trend', 'Короткие видео-обзоры продукта обгоняют текстовые обзоры по доверию', 'Собственники хотят видеть интерфейс и реальный сценарий работы, а не абстрактные обещания. Формат ''экран + 40 секунд сценария'' вызывает больше вопросов в комментариях, чем статичный пост.', '{"signal":"format_trend","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 60, 'used', '2026-10-04T12:45:14.244Z'),
('cmuttcznw0002euksx0bykf5z', 'builtin_research_pool', 'competitor_topic', 'Тема ''как принимать платежи'' - вечнозелёная в нише', 'Порядок приёма, подтверждения, депозиты и залоги регулярно поднимаются в сообществах арендодателей. Повод дать полезный материал без продаж в лоб.', '{"signal":"evergreen_topic","confidence":"high","source":"domain_research_pool","web":[]}', NULL, 50, 'used', '2026-10-04T12:45:14.253Z'),
('cmuttczo00003euks8awty4us', 'builtin_research_pool', 'seo_opportunity', 'Информационные запросы про учёт аренды и платежей', 'Кластер запросов вокруг учёта платежей, напоминаний об оплате и доходности портфеля. Интент информационный: человеку нужен порядок действий, а не сразу продукт.', '{"signal":"keyword_cluster","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 65, 'used', '2026-10-04T12:45:14.257Z'),
('cmuttd06a0004eukse4i6aqgg', 'builtin_research_pool', 'audience_question', 'Что фиксировать по каждому объекту, чтобы ничего не терять', 'Арендодатели просят чек-лист данных: договор, депозит, счётчики, контакты, история платежей, ремонты. Хороший повод для полезного контента.', '{"signal":"community_question","confidence":"high","source":"domain_research_pool","web":[]}', NULL, 70, 'used', '2026-10-04T12:45:14.914Z'),
('cmuttnoov0000euysylo83g67', 'builtin_research_pool', 'pain_point', 'Долги арендаторов замечают с опозданием на 2-4 недели', 'Без единой системы напоминаний просрочка платежа обнаруживается, когда собственник сам вспомнит проверить. К этому моменту долг уже накоплен, а разговор с арендатором превращается в конфликт.', '{"signal":"recurrent_theme","confidence":"medium","source":"domain_research_pool","web":[]}', NULL, 80, 'used', '2026-10-04T12:53:33.248Z'),
