('cmutzpjic0019eu7sd9sa0t6o', 'cmutzpjfr000xeu7sbh80eyss', 'x', 'x_thread', '{"tweets":["\"Как напоминать арендатору об оплате, чтобы не портить отношения\" - с этого разговора обычно и начинается наведение порядка в аренде.","Что теряется первым:\n- история платежей (в переписке)\n- договорённости (в памяти)\n- доходность по объектам (не считается)","Что даёт система: карточка объекта, статусы платежей по месяцам, напоминания арендатору и сводка по портфелю.","Ничего из этого не требует ''внедрения на месяц''. Начать можно с переноса текущих объектов. arendora.ru"],"cta":"arendora.ru"}', 'draft', 85, '{"score":85,"status":"rejected","checks":[{"check":"hook_strength","passed":true,"detail":"hook length 133 (expected 20-200)","weight":20},{"check":"clarity","passed":true,"detail":"payload length 480, placeholders/lorem absent","weight":10},{"check":"brand_safety","passed":true,"detail":"no fabricated claims detected","weight":25},{"check":"cta_quality","passed":true,"detail":"CTA present","weight":15},{"check":"platform_compliance","passed":true,"detail":"within platform limits","weight":15},{"check":"originality","passed":false,"detail":"max similarity with previous variants: 92%","weight":15}],"guardViolations":[]}', 1, '2026-10-04T15:42:57.541Z', '2026-10-04T15:42:57.548Z'),
